    const mixed=String(cfg?.searchUniverse||'mixed')==='mixed',equityPct=mixed?def.equityCap*100:100,nonFixedPct=mixed?Math.max(0,(1-finiteOr(def.fixedIncomeFloor,0))*100):100;
